INSERT INTO `clinical_templates` (`id`, `treatment_id`, `user_id`, `name`, `content`, `is_active`, `created_at`, `updated_at`) VALUES (1,3,NULL,'Limpieza dental','{\"procedures\": \"Se realizó profilaxis: destartraje supragingival con ultrasonido, pulido coronal y aplicación de flúor barniz.\", \"indications\": \"Cepillado 3 veces al día con técnica indicada. Uso de hilo dental. Control en 6 meses.\", \"chief_complaint\": \"Acude para control y limpieza dental.\"}',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(2,5,NULL,'Extracción simple','{\"procedures\": \"Anestesia infiltrativa, sindesmotomía, luxación y avulsión de la pieza. Hemostasia con gasa.\", \"indications\": \"No enjuagarse ni escupir por 24 horas. Morder la gasa 30 minutos. Dieta blanda y fría. Hielo en la zona por intervalos de 15 minutos. No fumar ni usar sorbete.\", \"prescription_items\": [{\"dose\": \"1 tableta\", \"duration\": \"3 días\", \"frequency\": \"cada 8 horas\", \"medication\": \"Ibuprofeno 400 mg\"}]}',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(3,4,NULL,'Curación con resina','{\"procedures\": \"Aislamiento relativo, remoción de caries, grabado ácido, adhesivo y restauración con resina fotocurable. Se ajusta oclusión y se pule.\", \"indications\": \"Puede comer normalmente. Si siente la mordida alta o molestia que no cede en 2 días, comuníquese con el consultorio.\"}',1,'2026-11-18 20:54:28','2026-11-18 20:54:28');
/*!40000 ALTER TABLE `clinical_templates` ENABLE KEYS */;
UNLOCK TABLES;

