INSERT INTO `consents` (`id`, `patient_id`, `consent_template_id`, `treatment_id`, `doctor_id`, `title`, `body_snapshot`, `signer_name`, `signer_document`, `signer_relationship`, `signature_path`, `clinical_file_id`, `signed_at`, `revoked_at`, `created_at`, `updated_at`) VALUES (1,3,1,7,1,'Consentimiento informado general · Endodoncia','Paciente: Rosa Huamán Torres.\n\nYo, Rosa Huamán Torres, identificado(a) con documento N.º 07654321, en mi calidad de paciente, autorizo a Dr. Jassmanny Neil Vega Jaen a realizar el tratamiento de endodoncia.\n\nSe me explicó en un lenguaje claro en qué consiste el tratamiento, sus beneficios, los riesgos y molestias más frecuentes, y las alternativas disponibles. Pude hacer preguntas y fueron respondidas.\n\nEntiendo que puedo retirar este consentimiento en cualquier momento antes del procedimiento.\n\nPor los antecedentes del paciente, se me explicó además que:\n• Tiene alergia a: Penicilina. No se usará ningún material ni medicamento que la contenga.\n• Por la presión alta, se le tomará la presión antes de la anestesia. Si está muy alta, el tratamiento se puede postergar.\n\nJuliaca, 18 de noviembre de 2026.','Rosa Huamán Torres','07654321','self','clinica/3/firmas/df99d5b1-d4c2-41cc-a273-d586de51f8d5.png',NULL,'2026-11-18 20:54:29',NULL,'2026-11-18 20:54:29','2026-11-18 20:54:29');
/*!40000 ALTER TABLE `consents` ENABLE KEYS */;
UNLOCK TABLES;

