INSERT INTO `faqs` (`id`, `question`, `answer`, `treatment_id`, `is_published`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'¿Cuánto cuesta la evaluación?','La evaluación cuesta S/ 50 e incluye la revisión completa y tu presupuesto.\n\nSi decides hacer el tratamiento con nosotros, la descontamos del total.',NULL,1,0,'2026-11-18 20:54:29','2026-11-18 20:54:29',NULL),(2,'¿Cómo pago?','En el consultorio, con efectivo, tarjeta, Yape o Plin. No se cobra nada al reservar en la web.',NULL,1,1,'2026-11-18 20:54:29','2026-11-18 20:54:29',NULL),(3,'¿Atienden a niños?','Sí, desde los 3 años. La primera visita es corta y tranquila para que se acostumbren.',NULL,1,2,'2026-11-18 20:54:29','2026-11-18 20:54:29',NULL),(4,'¿Cómo confirmo, cambio o cancelo mi cita?','Con el enlace que te enviamos por WhatsApp al reservar. Si faltan más de 24 horas, el cambio se hace al instante.',NULL,1,3,'2026-11-18 20:54:29','2026-11-18 20:54:29',NULL),(5,'¿El blanqueamiento daña los dientes?','Hecho por un dentista y con el producto adecuado, no daña el esmalte. Algunas personas sienten sensibilidad uno o dos días; pasa sola.',6,1,4,'2026-11-18 20:54:29','2026-11-18 20:54:29',NULL);
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

