INSERT INTO `message_templates` (`id`, `key`, `name`, `body`, `api_template_name`, `api_language`, `is_active`, `created_at`, `updated_at`) VALUES (1,'installment_reminder','Aviso de cuota por vencer','Hola {nombre}, te escribimos de {consultorio}.\nEl {fecha} vence tu {cuota} de {plan}: {monto}.\n\nPuedes pagarla en el consultorio con Yape, Plin, tarjeta o efectivo. Si ya la pagaste, no te preocupes.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(2,'installment_overdue','Cuota atrasada','Hola {nombre}, te escribimos de {consultorio}.\nTu {cuota} de {plan} venció el {fecha} y queda {monto} por pagar.\n\nPuedes pagarla en el consultorio con Yape, Plin, tarjeta o efectivo. Si ya la pagaste, avísanos y lo revisamos.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(3,'plan_follow_up','Presupuesto sin respuesta','Hola {nombre}, te escribimos de {consultorio}.\n¿Pudiste revisar tu plan de tratamiento con {doctor}? Si tienes dudas sobre el tratamiento o las formas de pago, escríbenos y te ayudamos.\n\nCuando quieras, te reservamos la primera cita.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(4,'plan_next_session','Plan sin próxima cita','Hola {nombre}, te escribimos de {consultorio}.\nEn tu tratamiento queda pendiente: {pendiente}.\n\n¿Te reservamos tu próxima cita? Respóndenos con el día y la hora que te acomodan.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(5,'checkup_recall','Le toca control','Hola {nombre}, te escribimos de {consultorio}.\nYa es momento de tu {control}. ¿Te reservamos una cita? Respóndenos con el día y la hora que te acomodan.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(6,'birthday','Saludo de cumpleaños','¡Feliz cumpleaños, {nombre}! 🎂 Todo el equipo de {consultorio} te desea un gran día.',NULL,'es',1,'2026-11-18 20:54:26','2026-11-18 20:54:26'),(7,'payment_receipt','Constancia de pago','Hola {nombre}, te escribimos de {consultorio}.\nRecibimos tu pago de {monto} ({medio}) el {fecha}. Constancia {numero}:\n{detalle}\n\nSaldo: {saldo}. ¡Gracias!',NULL,'es',1,'2026-11-18 20:54:27','2026-11-18 20:54:27'),(8,'review_request','Pedido de opinión en Google','Hola {nombre}, gracias por confiar en {consultorio}. Si te sentiste bien atendido, ¿nos dejas tu opinión en Google? Toma un minuto y ayuda a otras personas a encontrarnos:\n{opinion}',NULL,'es',1,'2026-11-18 20:54:27','2026-11-18 20:54:27'),(9,'campaign_announcement','Promoción a quien acepta recibirlas','Hola {nombre}, te escribimos de {consultorio}.\n{promocion}\nVale hasta el {hasta}.\n\nMira los detalles y reserva aquí:\n{pagina}\n\nSi prefieres no recibir promociones, respóndenos «no» y no te escribimos más.',NULL,'es',1,'2026-11-18 20:54:27','2026-11-18 20:54:27'),(10,'aftercare','Cuidados después de la atención','Hola {nombre}, gracias por venir hoy a {consultorio}. Para que tu {tratamiento} quede bien:\n\n{cuidados}\n\nSi tienes dolor fuerte, sangrado que no para o fiebre, escríbenos.',NULL,'es',1,'2026-11-18 20:54:27','2026-11-18 20:54:27'),(11,'missed_visit','Faltó o canceló y no tiene otra cita','Hola {nombre}, te escribimos de {consultorio}.\nNo pudimos verte en tu cita de {tratamiento} del {fecha}. ¿Te reservamos otro horario? Respóndenos con el día y la hora que te acomodan.',NULL,'es',1,'2026-11-18 20:54:27','2026-11-18 20:54:27'),(12,'booking_confirmation','Confirmación de reserva web','Hola {nombre} 👋, te escribimos de {consultorio}.\nTu cita de {tratamiento} quedó reservada para el {fecha} a las {hora} con {doctor}.\n{precio}\n\nConfirma tu asistencia, cambia el horario o cancela aquí:\n{enlace}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(13,'appointment_scheduled','Cita programada por el consultorio','Hola {nombre}, te escribimos de {consultorio}.\nTu próxima cita de {tratamiento} es el {fecha} a las {hora} con {doctor}.\n\nPuedes confirmarla aquí:\n{enlace}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(14,'appointment_reminder','Recordatorio de la cita','Hola {nombre}, te recordamos tu cita {cuando} a las {hora} con {doctor} en {consultorio}.\n{indicaciones}\n\nConfirma tu asistencia aquí:\n{enlace}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(15,'appointment_rescheduled','Cambio de horario','Hola {nombre}, tu cita de {tratamiento} cambió al {fecha} a las {hora} con {doctor}.\n\nConfirma el nuevo horario aquí:\n{enlace}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(16,'appointment_cancelled','Cita cancelada por el consultorio','Hola {nombre}, lamentamos avisarte que tu cita del {fecha} a las {hora} fue cancelada. Escríbenos y te ayudamos a elegir otro horario.',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(17,'reschedule_approved','Solicitud de cambio aprobada','Hola {nombre}, aprobamos tu cambio. Tu cita de {tratamiento} ahora es el {fecha} a las {hora} con {doctor}.\n\nDetalles aquí:\n{enlace}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(18,'reschedule_rejected','Solicitud de cambio no aprobada','Hola {nombre}, no pudimos mover tu cita a los horarios que propusiste. Tu cita sigue el {fecha} a las {hora}. Escríbenos y buscamos otra opción.',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(19,'access_link','Enlace de acceso a Mi cuenta','Hola, este es tu enlace para entrar a Mi cuenta en {consultorio}:\n{enlace}\n\nNo lo compartas con nadie.',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(20,'prescription','Receta e indicaciones','Hola {nombre}, te enviamos tu receta e indicaciones de {doctor}:\n\n{receta}',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(21,'treatment_plan','Plan de tratamiento (presupuesto)','Hola {nombre}, te enviamos tu plan de tratamiento con {doctor}:\n\n{plan}\n\nTotal: {total}{vigencia}\nEs un presupuesto referencial: si en el camino el tratamiento cambia, te lo explicamos antes. Cualquier duda, escríbenos.',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28'),(22,'waitlist_offer','Horario libre para lista de espera','Hola {nombre}, se liberó un horario para {tratamiento} el {fecha} a las {hora} con {doctor}. Te lo guardamos hasta las {hasta}: ¿lo quieres? Respóndenos y te lo reservamos.',NULL,'es',1,'2026-11-18 20:54:28','2026-11-18 20:54:28');
/*!40000 ALTER TABLE `message_templates` ENABLE KEYS */;
UNLOCK TABLES;

