INSERT INTO `text_snippets` (`id`, `user_id`, `field`, `label`, `body`, `shortcut`, `status`, `created_at`, `updated_at`) VALUES (1,NULL,'chief_complaint','Dolor dental','Paciente refiere dolor en pieza ',NULL,'active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(2,NULL,'chief_complaint','Control y limpieza','Acude para control y limpieza dental.',NULL,'active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(3,NULL,'chief_complaint','Sensibilidad','Refiere sensibilidad al frío y al dulce.',NULL,'active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(4,NULL,'clinical_exam','Examen sin alteraciones','Extraoral: sin alteraciones. Intraoral: mucosas hidratadas, de color rosado, sin lesiones.','normal','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(5,NULL,'procedures','Profilaxis completa','Se realizó profilaxis: destartraje supragingival con ultrasonido, pulido coronal y aplicación de flúor barniz.','limp','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(6,NULL,'procedures','Restauración con resina','Aislamiento relativo, remoción de caries, grabado ácido, adhesivo y restauración con resina fotocurable. Se ajusta oclusión y se pule.','res','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(7,NULL,'procedures','Extracción simple','Anestesia infiltrativa, sindesmotomía, luxación y avulsión de la pieza. Hemostasia con gasa. Se dan indicaciones.','ext','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(8,NULL,'indications','Indicaciones post-extracción','No enjuagarse ni escupir por 24 horas. Morder la gasa 30 minutos. Dieta blanda y fría. Hielo en la zona por intervalos de 15 minutos. No fumar ni usar sorbete.','postex','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(9,NULL,'indications','Indicaciones post-resina','Puede comer normalmente. Si siente la mordida alta o molestia que no cede en 2 días, comuníquese con el consultorio.','postres','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(10,NULL,'prescription','Ibuprofeno 400 mg','Ibuprofeno 400 mg: 1 tableta cada 8 horas por 3 días, después de los alimentos.','ibu','active','2026-11-18 20:54:28','2026-11-18 20:54:28'),(11,NULL,'prescription','Paracetamol 500 mg','Paracetamol 500 mg: 1 tableta cada 8 horas por 3 días, si hay dolor.','para','active','2026-11-18 20:54:28','2026-11-18 20:54:28');
