INSERT INTO `treatments` (`id`, `name`, `slug`, `kind`, `summary`, `description`, `price_from`, `show_price`, `duration_minutes`, `buffer_minutes`, `sessions_label`, `checkup_months`, `next_session_days`, `before_instructions`, `aftercare`, `is_evaluation`, `online_bookable`, `is_public`, `image_path`, `seo_title`, `seo_description`, `sort_order`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'Evaluación o primera consulta','evaluacion-o-primera-consulta',NULL,'Revisión completa, diagnóstico y presupuesto. Si no sabes qué necesitas, empieza aquí.',NULL,50.00,1,30,NULL,'1',NULL,NULL,NULL,NULL,1,1,1,NULL,NULL,NULL,1,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(2,'Control de ortodoncia','control-de-ortodoncia',NULL,'Ajuste y seguimiento de tus brackets o alineadores.',NULL,150.00,1,30,NULL,'Una vez al mes',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,2,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(3,'Limpieza dental','limpieza-dental',NULL,'Retiro de sarro y placa, y pulido. Lo ideal es hacerla cada seis meses.','La limpieza retira el sarro y la placa que el cepillo no alcanza, sobre todo entre los dientes y bajo la encía. Así se previenen las caries, el sangrado de encías y el mal aliento.\n\n## Cómo es la sesión\n\n1. Revisamos tus dientes y encías.\n2. Retiramos el sarro con ultrasonido y pulimos.\n3. Te damos indicaciones de cepillado según lo que vimos.\n\nDura unos 45 minutos y no duele; si tienes las encías sensibles, avísanos y vamos más despacio.',120.00,1,45,NULL,'1',NULL,NULL,NULL,NULL,0,1,1,NULL,NULL,NULL,3,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(4,'Curación con resina','curacion-con-resina',NULL,'Repara caries o dientes rotos con resina del color de tu diente.',NULL,150.00,1,60,NULL,'1',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,4,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(5,'Extracción simple','extraccion-simple',NULL,'Retiro de una pieza dañada, con anestesia local.',NULL,150.00,1,45,NULL,'1',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,5,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(6,'Blanqueamiento','blanqueamiento',NULL,'Aclara el color de tus dientes en el consultorio, con control del dentista.',NULL,450.00,1,90,NULL,'1 – 2',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,6,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(7,'Endodoncia','endodoncia',NULL,'Tratamiento de conducto para salvar un diente con el nervio dañado.',NULL,600.00,1,90,NULL,'1 – 3',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,7,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(8,'Colocación de brackets','colocacion-de-brackets',NULL,'Inicio de tu ortodoncia para alinear los dientes y la mordida.',NULL,2500.00,1,120,NULL,'1',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,8,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL),(9,'Implante','implante',NULL,'Reemplaza un diente perdido con una raíz de titanio y una corona.',NULL,3500.00,1,120,NULL,'Varias sesiones',NULL,NULL,NULL,NULL,0,0,1,NULL,NULL,NULL,9,1,'2026-11-18 20:54:28','2026-11-18 20:54:29',NULL);
